/*
 * test_provision_boot.c
 *
 * Host tests for the real one-shot provisioning entry
 * (onboard/startup_fram_provision_boot.c), compiled with the header generated by
 * the host tool, so a generator/writer symbol or size mismatch fails here.
 *
 * The entry never returns by design: it requests NVIC_SystemReset() on any
 * provisioning failure and parks in __WFI() after a verified success. The host
 * build turns those two points into longjmps so each outcome can be asserted,
 * including that the deployment outputs are commanded OFF first and last.
 */

#include <setjmp.h>
#include <string.h>

#include "stm32l476xx.h" /* host register/reset model */

#include "contract_fixture.h"
#include "framework.h"
#include "fram_device_fake.h"
#include "startup_fram_image.h" /* generated: --header-symbol STARTUP_FRAM_PROVISION_IMAGE */
#include "startup_fram_provision.h"
#include "startup_fram_provision_report.h"

int startup_fram_provision_boot(void);

/* Instances of the register-model globals declared by the host CMSIS stub. */
GPIO_TypeDef fake_gpio_a;
GPIO_TypeDef fake_gpio_b;
GPIO_TypeDef fake_gpio_c;
SPI_TypeDef fake_spi1;
RCC_TypeDef fake_rcc;

static jmp_buf entry_exit;
static unsigned reset_requests;
static unsigned park_entries;
static unsigned pyro_off_calls;
static unsigned pyro_on_calls;

void fake_request_reset(void)
{
    reset_requests++;
    longjmp(entry_exit, 1); /* outcome 1: reset path */
}

void fake_park(void)
{
    park_entries++;
    longjmp(entry_exit, 2); /* outcome 2: success path parked */
}

/* Platform seams the entry uses; they must stay side-effect free in this test. */
void pdb_init(void)
{
}

void pdb_pyro_off(void)
{
    pyro_off_calls++;
}

void pdb_pyro_on(void)
{
    pyro_on_calls++;
}

void led_init(void)
{
}

void init_coreClocks(void)
{
}

bool heartbeat_timer_init(void)
{
    return true;
}

void spi_config(SPI_TypeDef *spi)
{
    (void)spi;
}

static void reset_observations(void)
{
    fake_fram_reset();
    reset_requests = 0u;
    park_entries = 0u;
    pyro_off_calls = 0u;
    pyro_on_calls = 0u;
}

static int run_entry(void)
{
    const int outcome = setjmp(entry_exit);
    if (outcome == 0) {
        (void)startup_fram_provision_boot();
        return 0;
    }
    return outcome;
}

static const volatile StartupFramProvisionReport *report(void)
{
    return &startup_fram_provision_report;
}

static bool device_matches_generated_image(void)
{
    for (uint16_t address = 0; address < STARTUP_FRAM_PROVISION_IMAGE_SIZE; address++) {
        if (fake_fram_byte(address) != STARTUP_FRAM_PROVISION_IMAGE[address]) {
            return false;
        }
    }
    return true;
}

static void test_generated_header_is_the_contract_image(void)
{
    TEST_ASSERT(STARTUP_FRAM_PROVISION_IMAGE_SIZE == STARTUP_FRAM_IMAGE_SIZE);
    TEST_ASSERT(sizeof(STARTUP_FRAM_PROVISION_IMAGE) == STARTUP_FRAM_IMAGE_SIZE);
    TEST_ASSERT(startup_fram_image_is_valid(STARTUP_FRAM_PROVISION_IMAGE,
                                            sizeof(STARTUP_FRAM_PROVISION_IMAGE)));
    /* Unarmed and at the initial checks by default: the header must not arm. */
    TEST_ASSERT(STARTUP_FRAM_PROVISION_IMAGE_ARMED == 0u);
    TEST_ASSERT((STARTUP_FRAM_PROVISION_IMAGE[8 + STARTUP_FRAM_SLOT_FLAGS_OFFSET]
                 & STARTUP_FRAM_FLAG_ARMED)
                == 0u);
    TEST_ASSERT(STARTUP_FRAM_PROVISION_IMAGE_BOOT_COUNT == 0u);
    TEST_ASSERT(STARTUP_FRAM_PROVISION_IMAGE_ADCS_MASK == 0u);
}

static void test_success_parks_with_pyro_off_and_exact_image(void)
{
    reset_observations();
    fake_fram_fill(0xAAu);

    TEST_ASSERT(run_entry() == 2);
    TEST_ASSERT(reset_requests == 0u);
    TEST_ASSERT(park_entries == 1u);
    TEST_ASSERT(pyro_off_calls == 2u); /* before the writes and after them */
    TEST_ASSERT(pyro_on_calls == 0u);
    TEST_ASSERT(device_matches_generated_image());
    TEST_ASSERT(!fake_fram_out_of_range());

    /* The debugger-visible report describes the device's own read-back. */
    TEST_ASSERT(report()->magic == STARTUP_FRAM_REPORT_MAGIC);
    TEST_ASSERT(report()->version == STARTUP_FRAM_REPORT_VERSION);
    TEST_ASSERT(report()->status == STARTUP_FRAM_PROVISION_OK);
    TEST_ASSERT(report()->image_valid == 1u);
    TEST_ASSERT(report()->device_read_ok == 1u);
    TEST_ASSERT(report()->readback_matches == 1u);
    TEST_ASSERT(report()->mismatch_count == 0u);
    TEST_ASSERT(report()->first_mismatch_addr == STARTUP_FRAM_REPORT_ADDR_NONE);
    TEST_ASSERT(report()->readback_boot_counter == 0u);
    TEST_ASSERT(report()->readback_adcs_mask == 0u);
    TEST_ASSERT(report()->readback_slot_a_marker == STARTUP_FRAM_COMMIT_MARKER);
    TEST_ASSERT(report()->readback_slot_b_marker == STARTUP_FRAM_COMMIT_MARKER);
    TEST_ASSERT(memcmp((const void *)report()->intended, STARTUP_FRAM_PROVISION_IMAGE,
                       STARTUP_FRAM_PROVISION_IMAGE_SIZE) == 0);
    TEST_ASSERT(memcmp((const void *)report()->readback, STARTUP_FRAM_PROVISION_IMAGE,
                       STARTUP_FRAM_PROVISION_IMAGE_SIZE) == 0);
    TEST_ASSERT(sizeof(StartupFramProvisionReport)
                == 48u + 48u + 12u * sizeof(uint32_t));
}

static void test_failure_requests_reset_with_pyro_off(void)
{
    reset_observations();
    fake_fram_fill(0xAAu);
    fake_fram_fail_write(0u, FAKE_FAULT_HARD_ERROR, 0u);

    TEST_ASSERT(run_entry() == 1);
    TEST_ASSERT(reset_requests == 1u);
    TEST_ASSERT(park_entries == 0u);
    TEST_ASSERT(pyro_off_calls == 2u);
    TEST_ASSERT(pyro_on_calls == 0u);
    /* Nothing may be published after a failed invalidation. */
    TEST_ASSERT(fake_fram_byte(8 + STARTUP_FRAM_SLOT_MARKER_OFFSET) != STARTUP_FRAM_COMMIT_MARKER);
    TEST_ASSERT(fake_fram_byte(28 + STARTUP_FRAM_SLOT_MARKER_OFFSET) != STARTUP_FRAM_COMMIT_MARKER);
}

static void test_report_shows_a_device_readback_that_differs(void)
{
    reset_observations();
    fake_fram_fill(0xAAu);
    fake_fram_fail_write(0u, FAKE_FAULT_HARD_ERROR, 0u);

    TEST_ASSERT(run_entry() == 1);
    TEST_ASSERT(report()->status == STARTUP_FRAM_PROVISION_INVALIDATE_FAILED);
    TEST_ASSERT(report()->image_valid == 1u);
    TEST_ASSERT(report()->device_read_ok == 1u);
    TEST_ASSERT(report()->readback_matches == 0u);
    TEST_ASSERT(report()->mismatch_count == STARTUP_FRAM_IMAGE_SIZE);
    TEST_ASSERT(report()->first_mismatch_addr == 0u);
    /* The report reflects the untouched device, not the intended image. */
    TEST_ASSERT(report()->readback[0] == 0xAAu);
    TEST_ASSERT(report()->intended[0] == STARTUP_FRAM_PROVISION_IMAGE[0]);
    TEST_ASSERT(report()->readback_slot_a_marker != STARTUP_FRAM_COMMIT_MARKER);
    TEST_ASSERT(report()->readback_slot_b_marker != STARTUP_FRAM_COMMIT_MARKER);
}

static void test_report_separates_unconfirmed_success_from_a_match(void)
{
    reset_observations();
    fake_fram_fill(0xAAu);
    /* The last commit lands but the response is lost: the device holds the whole
     * new image while the writer cannot confirm it. */
    fake_fram_fail_write(5u, FAKE_FAULT_LOST_RESPONSE, 0u);

    TEST_ASSERT(run_entry() == 1);
    TEST_ASSERT(report()->status == STARTUP_FRAM_PROVISION_COMMIT_FAILED);
    TEST_ASSERT(report()->readback_matches == 1u);
    TEST_ASSERT(report()->mismatch_count == 0u);
    TEST_ASSERT(reset_requests == 1u); /* reset anyway: unconfirmed, never assume */
    TEST_ASSERT(pyro_off_calls == 2u);
}

int main(void)
{
    TEST_SUITE("provisioning boot entry");
    RUN_TEST(test_generated_header_is_the_contract_image);
    RUN_TEST(test_success_parks_with_pyro_off_and_exact_image);
    RUN_TEST(test_failure_requests_reset_with_pyro_off);
    RUN_TEST(test_report_shows_a_device_readback_that_differs);
    RUN_TEST(test_report_separates_unconfirmed_success_from_a_match);
    TEST_RESULTS();
}
